1: // UI-10/12/13, EV-SRC-003, EV-REG-003/007. All final validation remains server-side.
2: (() => { const editor=document.querySelector('[data-editor-form]'); let dirty=false,leaving=false;
3: if(editor){editor.addEventListener('input',()=>{dirty=true;const token=editor.querySelector('[name="Input.DuplicateToken"]');if(token)token.value='';});window.addEventListener('beforeunload',e=>{if(dirty&&!leaving){e.preventDefault();e.returnValue='';}});}
4: for(const form of document.forms){form.addEventListener('submit',event=>{const button=event.submitter;const prompt=button?.dataset.confirm||form.dataset.confirm;if(prompt&&!window.confirm(prompt)){event.preventDefault();return;}leaving=true;for(const action of form.querySelectorAll('button')){if(action!==button)action.disabled=true;}form.setAttribute('aria-busy','true');});}
5: for(const link of document.querySelectorAll('[data-dirty-link]')){link.addEventListener('click',e=>{if(dirty&&!window.confirm(link.dataset.confirm||'保存していない変更を破棄しますか。'))e.preventDefault();else leaving=true;});}
